import{_ as o,a0 as l,w as r,s as d,ao as p,I as e,x as a,a1 as t,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const P=JSON.parse('{"title":"如何在 Fedora 上使用 Poetry 来管理你的 Python 项目？ | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Fedora 上使用 Poetry 来管理你的 Python 项目？ | LCTT (202103) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Fedora 上使用 Poetry 来管理你的 Python 项目？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Fedora 上使用 Poetry 来管理你的 Python 项目？ | LCTT (202103) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202103/20210308 How to use Poetry to manage your Python projects on Fedora","title":"如何在 Fedora 上使用 Poetry 来管理你的 Python 项目？","tag":"202103","desc":""},"relativePath":"202103/20210308 How to use Poetry to manage your Python projects on Fedora.md","filePath":"[post].md"}'),h={name:"202103/20210308 How to use Poetry to manage your Python projects on Fedora.md"};function g(c,s,u,y,k,b){const n=l("Link");return r(),d("div",null,[s[24]||(s[24]=p(`<h1 id="如何在-fedora-上使用-poetry-来管理你的-python-项目" tabindex="-1">如何在 Fedora 上使用 Poetry 来管理你的 Python 项目？ <a class="header-anchor" href="#如何在-fedora-上使用-poetry-来管理你的-python-项目" aria-label="Permalink to “如何在 Fedora 上使用 Poetry 来管理你的 Python 项目？”">​</a></h1><p><img src="https://fedoramagazine.org/wp-content/uploads/2021/03/Poetry_Python-816x345.jpg" alt="Python &amp; Poetry on Fedora"></p><p>Python 开发人员经常创建一个新的虚拟环境来分离项目依赖，然后用 <code>pip</code>、<code>pipenv</code> 等工具来管理它们。Poetry 是一个简化 Python 中依赖管理和打包的工具。这篇文章将向你展示如何在 Fedora 上使用 Poetry 来管理你的 Python 项目。</p><p>与其他工具不同，Poetry 只使用一个配置文件来进行依赖管理、打包和发布。这消除了对不同文件的需求，如 <code>Pipfile</code>、<code>MANIFEST.in</code>、<code>setup.py</code> 等。这也比使用多个工具更快。</p><p>下面详细介绍一下开始使用 Poetry 时使用的命令。</p><h3 id="在-fedora-上安装-poetry" tabindex="-1">在 Fedora 上安装 Poetry <a class="header-anchor" href="#在-fedora-上安装-poetry" aria-label="Permalink to “在 Fedora 上安装 Poetry”">​</a></h3><p>如果你已经使用 Fedora 32 或以上版本，你可以使用这个命令直接从命令行安装 Poetry：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install poetry</span></span></code></pre></div><p>编者注：在 Fedora Silverblue 或 CoreOs上，Python 3.9.2 是核心提交的一部分，你可以用下面的命令安装 Poetry：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rpm-ostree install poetry</span></span></code></pre></div><h3 id="初始化一个项目" tabindex="-1">初始化一个项目 <a class="header-anchor" href="#初始化一个项目" aria-label="Permalink to “初始化一个项目”">​</a></h3><p>使用 <code>new</code> 命令创建一个新项目：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ poetry new poetry-project</span></span></code></pre></div><p>用 Poetry 创建的项目结构是这样的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>├── poetry_project</span></span>
<span class="line"><span>│   └── init.py</span></span>
<span class="line"><span>├── pyproject.toml</span></span>
<span class="line"><span>├── README.rst</span></span>
<span class="line"><span>└── tests</span></span>
<span class="line"><span>    ├── init.py</span></span>
<span class="line"><span>    └── test_poetry_project.py</span></span></code></pre></div><p>Poetry 使用 <code>pyproject.toml</code> 来管理项目的依赖。最初，这个文件看起来类似于这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[tool.poetry]</span></span>
<span class="line"><span>name = &quot;poetry-project&quot;</span></span>
<span class="line"><span>version = &quot;0.1.0&quot;</span></span>
<span class="line"><span>description = &quot;&quot;</span></span>
<span class="line"><span>authors = [&quot;Kadermiyanyedi &lt;kadermiyanyedi@hotmail.com&gt;&quot;]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[tool.poetry.dependencies]</span></span>
<span class="line"><span>python = &quot;^3.9&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[tool.poetry.dev-dependencies]</span></span>
<span class="line"><span>pytest = &quot;^5.2&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[build-system]</span></span>
<span class="line"><span>requires = [&quot;poetry&gt;=0.12&quot;]</span></span>
<span class="line"><span>build-backend = &quot;poetry.masonry.api&quot;</span></span></code></pre></div><p>这个文件包含 4 个部分：</p>`,18)),e("ul",null,[s[3]||(s[3]=e("li",null,"第一部分包含描述项目的信息，如项目名称、项目版本等。",-1)),s[4]||(s[4]=e("li",null,"第二部分包含项目的依赖。这些依赖是构建项目所必需的。",-1)),s[5]||(s[5]=e("li",null,"第三部分包含开发依赖。",-1)),e("li",null,[s[1]||(s[1]=a("第四部分描述的是符合 ",-1)),t(n,{href:"https://www.python.org/dev/peps/pep-0517/"},{default:i(()=>[...s[0]||(s[0]=[a("PEP 517",-1)])]),_:1}),s[2]||(s[2]=a(" 的构建系统。",-1))])]),s[25]||(s[25]=p(`<p>如果你已经有一个项目，或者创建了自己的项目文件夹，并且你想使用 Poetry，请在你的项目中运行 <code>init</code> 命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ poetry init</span></span></code></pre></div><p>在这个命令之后，你会看到一个交互式的 shell 来配置你的项目。</p><h3 id="创建一个虚拟环境" tabindex="-1">创建一个虚拟环境 <a class="header-anchor" href="#创建一个虚拟环境" aria-label="Permalink to “创建一个虚拟环境”">​</a></h3><p>如果你想创建一个虚拟环境或激活一个现有的虚拟环境，请使用以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ poetry shell</span></span></code></pre></div><p>Poetry 默认在 <code>/home/username/.cache/pypoetry</code> 项目中创建虚拟环境。你可以通过编辑 Poetry 配置来更改默认路径。使用下面的命令查看配置列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ poetry config --list</span></span>
<span class="line"><span></span></span>
<span class="line"><span>cache-dir = &quot;/home/username/.cache/pypoetry&quot;</span></span>
<span class="line"><span>virtualenvs.create = true</span></span>
<span class="line"><span>virtualenvs.in-project = true</span></span>
<span class="line"><span>virtualenvs.path = &quot;{cache-dir}/virtualenvs&quot;</span></span></code></pre></div><p>修改 <code>virtualenvs.in-project</code> 配置变量，在项目目录下创建一个虚拟环境。Poetry 命令是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ poetry config virtualenv.in-project true</span></span></code></pre></div><h3 id="添加依赖" tabindex="-1">添加依赖 <a class="header-anchor" href="#添加依赖" aria-label="Permalink to “添加依赖”">​</a></h3><p>使用 <code>poetry add</code> 命令为项目安装一个依赖：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ poetry add django</span></span></code></pre></div><p>你可以使用带有 <code>--dev</code> 选项的 <code>add</code> 命令来识别任何只用于开发环境的依赖：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ poetry add black --dev</span></span></code></pre></div><p><code>add</code> 命令会创建一个 <code>poetry.lock</code> 文件，用来跟踪软件包的版本。如果 <code>poetry.lock</code> 文件不存在，那么会安装 <code>pyproject.toml</code> 中所有依赖项的最新版本。如果 <code>poetry.lock</code> 存在，Poetry 会使用文件中列出的确切版本，以确保每个使用这个项目的人的软件包版本是一致的。</p><p>使用 <code>poetry install</code> 命令来安装当前项目中的所有依赖：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ poetry install</span></span></code></pre></div><p>通过使用 <code>--no-dev</code> 选项防止安装开发依赖：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ poetry install --no-dev</span></span></code></pre></div><h3 id="列出软件包" tabindex="-1">列出软件包 <a class="header-anchor" href="#列出软件包" aria-label="Permalink to “列出软件包”">​</a></h3><p><code>show</code> 命令会列出所有可用的软件包。<code>--tree</code> 选项将以树状列出软件包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ poetry show --tree</span></span>
<span class="line"><span></span></span>
<span class="line"><span>django 3.1.7 A high-level Python Web framework that encourages rapid development and clean, pragmatic design.</span></span>
<span class="line"><span>├── asgiref &gt;=3.2.10,&lt;4</span></span>
<span class="line"><span>├── pytz *</span></span>
<span class="line"><span>└── sqlparse &gt;=0.2.2</span></span></code></pre></div><p>包含软件包名称，以列出特定软件包的详细信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ poetry show requests</span></span>
<span class="line"><span></span></span>
<span class="line"><span>name         : requests</span></span>
<span class="line"><span>version      : 2.25.1</span></span>
<span class="line"><span>description  : Python HTTP for Humans.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>dependencies</span></span>
<span class="line"><span> - certifi &gt;=2017.4.17</span></span>
<span class="line"><span> - chardet &gt;=3.0.2,&lt;5</span></span>
<span class="line"><span> - idna &gt;=2.5,&lt;3</span></span>
<span class="line"><span> - urllib3 &gt;=1.21.1,&lt;1.27</span></span></code></pre></div><p>最后，如果你想知道软件包的最新版本，你可以通过 <code>--latest</code> 选项：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ poetry show --latest</span></span>
<span class="line"><span></span></span>
<span class="line"><span>idna     2.10      3.1    Internationalized Domain Names in Applications</span></span>
<span class="line"><span>asgiref  3.3.1     3.3.1  ASGI specs, helper code, and adapters</span></span></code></pre></div><h3 id="更多信息" tabindex="-1">更多信息 <a class="header-anchor" href="#更多信息" aria-label="Permalink to “更多信息”">​</a></h3>`,28)),e("p",null,[s[7]||(s[7]=a("Poetry 的更多详情可在",-1)),t(n,{href:"https://python-poetry.org/docs/"},{default:i(()=>[...s[6]||(s[6]=[a("文档",-1)])]),_:1}),s[8]||(s[8]=a("中获取。",-1))]),s[26]||(s[26]=e("hr",null,null,-1)),e("p",null,[s[10]||(s[10]=a("via: ",-1)),t(n,{href:"https://fedoramagazine.org/how-to-use-poetry-to-manage-your-python-projects-on-fedora/"},{default:i(()=>[...s[9]||(s[9]=[a("https://fedoramagazine.org/how-to-use-poetry-to-manage-your-python-projects-on-fedora/",-1)])]),_:1})]),e("p",null,[s[15]||(s[15]=a("作者：",-1)),t(n,{href:"https://fedoramagazine.org/author/moonkat/"},{default:i(()=>[...s[11]||(s[11]=[a("Kader Miyanyedi",-1)])]),_:1}),s[16]||(s[16]=a(" 选题：",-1)),t(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[12]||(s[12]=[a("lujun9972",-1)])]),_:1}),s[17]||(s[17]=a(" 译者：",-1)),t(n,{href:"https://github.com/geekpi"},{default:i(()=>[...s[13]||(s[13]=[a("geekpi",-1)])]),_:1}),s[18]||(s[18]=a(" 校对：",-1)),t(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[14]||(s[14]=[a("wxy",-1)])]),_:1})]),e("p",null,[s[21]||(s[21]=a("本文由 ",-1)),t(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[19]||(s[19]=[a("LCTT",-1)])]),_:1}),s[22]||(s[22]=a(" 原创编译，",-1)),t(n,{href:"https://linux.cn/"},{default:i(()=>[...s[20]||(s[20]=[a("Linux中国",-1)])]),_:1}),s[23]||(s[23]=a(" 荣誉推出",-1))])])}const v=o(h,[["render",g]]);export{P as __pageData,v as default};
